import { z } from 'zod';
import type { SourceFamily } from '../types/source-sync';

interface SourceRefreshCommand {
  method: 'GET' | 'POST';
  endpoint: string;
  body: unknown;
}

export const sourceRefreshScope = ({
  family,
  positionals,
  isAll,
  isPreview,
}: {
  family: SourceFamily;
  positionals: readonly string[];
  isAll: boolean;
  isPreview: boolean;
}): SourceRefreshCommand | { sourceId: string } => {
  const scopes = [positionals.length > 0, isAll, isPreview].filter(Boolean);
  if (scopes.length !== 1 || positionals.length > 1)
    throw new z.ZodError([
      {
        code: 'custom',
        path: ['refresh'],
        message: 'Pass exactly one source ID, --all, or --preview',
      },
    ]);
  if (isPreview)
    return {
      method: 'GET',
      endpoint: `/profile/source-sync?family=${family}`,
      body: undefined,
    };
  if (isAll)
    return {
      method: 'POST',
      endpoint: '/profile/source-sync/refreshes',
      body: { all: true, family },
    };
  return { sourceId: positionals[0] };
};
